// Splendor's approved corporate letterhead assets -- the real, approved
// header banner and footer contact bar (extracted from the company's
// official 600 DPI letterhead PDF, provided directly by the user
// 2026-09-03), used by every document this system generates
// (corporateDocumentEngine.ts's LPOs/invoices/receipts/statements/letters
// and leaseToOwnContractDocument.ts's LTO contracts). These constants
// previously held a 1x1 transparent-green placeholder pixel left over from
// early development and never replaced -- every document generated before
// this fix rendered with a blank green header/footer instead of the real
// letterhead. See docs/DOCUMENT_LETTERHEAD.md.
//
// Header is JPEG (a photographic Dubai skyline background compresses far
// smaller than PNG at equivalent visual quality); footer is PNG (a flat
// color bar with sharp white text/icons, where PNG's lossless compression
// is both smaller and artifact-free for that content).
export const LTO_LETTERHEAD_HEADER_JPEG_BASE64 = "";
export const LTO_LETTERHEAD_FOOTER_PNG_BASE64 = "";
